import griffe
from griffe import Docstring, Extension


class AppendCheckedExtension(Extension):
    def on_function_instance(self, *, node, func, agent, **kwargs) -> None:
        if func.docstring is not None:
            func.docstring.value += " [checked]"
        else:
            func.docstring = Docstring(" [checked]", parent=func)


extensions = griffe.load_extensions(AppendCheckedExtension())

module = griffe.load("mypkg", extensions=extensions)

